-- Last published list prices for retired models whose price rows are gone.
--
-- v2_model_successor_price_ratio falls back to reference_prices when the old
-- model has no price rows left, so the default "never pay more" policy can
-- compare a successor's price. Prices are the vendor's standard list price
-- (base context tier, no batch or promotions) from official pricing pages,
-- deprecation notices or archived copies of them; each row names its source.
-- Models that were free or never had a public price are left without one,
-- so their prices stay not comparable.
--
-- Only rows without reference prices are filled, so an admin's edit is kept.

UPDATE "public"."v2_model_successor_routing" AS s
SET reference_prices = v.prices::jsonb, reference_price_source = v.source, updated_at = now()
FROM (VALUES
